<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Services;
use PDO; use PHPUnit\Framework\TestCase; use Sentinel\Core\Config; use Sentinel\Core\Database; use Sentinel\Core\HttpException; use Sentinel\Core\RuntimeContext; use Sentinel\Repositories\AuditRepository; use Sentinel\Repositories\DeviceSessionRepository; use Sentinel\Services\AuditService; use Sentinel\Services\DeviceSessionManagementService;
final class DeviceSessionManagementServiceTest extends TestCase { private function service():array{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));foreach(['devices (device_id INTEGER,company_id INTEGER,device_status TEXT,deleted_at TEXT,last_seen_at TEXT)','employees (employee_id INTEGER,company_id INTEGER)','device_assignments (device_assignment_id INTEGER,company_id INTEGER,device_id INTEGER,employee_id INTEGER,employee_assignment_id INTEGER,assignment_status TEXT,ends_at TEXT)','employee_assignments (employee_assignment_id INTEGER,company_id INTEGER,employee_id INTEGER,deleted_at TEXT)','shift_assignments (shift_assignment_id INTEGER,company_id INTEGER,employee_id INTEGER,site_id INTEGER,deleted_at TEXT)','sites (site_id INTEGER,company_id INTEGER)','device_sessions (device_session_id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER,device_id INTEGER,device_assignment_id INTEGER,employee_id INTEGER,employee_assignment_id INTEGER,shift_assignment_id INTEGER,site_id INTEGER,session_status TEXT,started_at TEXT,ended_at TEXT,last_seen_at TEXT,created_at TEXT,updated_at TEXT)','audit_logs (audit_log_id INTEGER PRIMARY KEY,company_id INTEGER,user_id INTEGER,entity_name TEXT,entity_id TEXT,action_name TEXT,action_status TEXT,ip_address TEXT,user_agent TEXT,old_values TEXT,new_values TEXT,metadata TEXT)']as$sql)$db->execute('CREATE TABLE '.$sql);$db->execute("INSERT INTO devices VALUES (1,101,'ACTIVE',NULL,NULL),(2,202,'ACTIVE',NULL,NULL)");$db->execute('INSERT INTO employees VALUES (7,101),(8,202)');$db->execute("INSERT INTO device_assignments VALUES (4,101,1,7,11,'ACTIVE',NULL)");$db->execute('INSERT INTO employee_assignments VALUES (11,101,7,NULL)');$db->execute('INSERT INTO shift_assignments VALUES (12,101,7,3,NULL)');$db->execute('INSERT INTO sites VALUES (3,101)');$context=new RuntimeContext();$context->setTenantId(101);$context->setUser('7');return[new DeviceSessionManagementService(new DeviceSessionRepository($db,$context),new AuditService(new AuditRepository($db,$context),$context)),$db];} public function testActiveAssignmentSessionStartsAndEndsWithoutReopening():void{[$service,$db]=$this->service();$session=$service->startSession(['device_id'=>1,'device_assignment_id'=>4,'employee_id'=>7,'employee_assignment_id'=>11,'shift_assignment_id'=>12,'site_id'=>3,'started_at'=>'2026-09-14 08:00:00']);self::assertSame('ACTIVE',$session['session_status']);try{$service->startSession(['device_id'=>1,'employee_id'=>7]);self::fail();}catch(HttpException $e){self::assertSame(409,$e->statusCode());}$ended=$service->endSession((string)$session['device_session_id'],['ended_at'=>'2026-09-14 09:00:00']);self::assertSame('ENDED',$ended['session_status']);try{$service->endSession((string)$session['device_session_id'],['ended_at'=>'2026-09-14 10:00:00']);self::fail();}catch(HttpException $e){self::assertSame(422,$e->statusCode());}self::assertSame('2',(string)$db->fetch('SELECT COUNT(*) total FROM audit_logs')['total']);} }